    if (vidArg) vid = String(vidArg);
    var m1 = /[?&]vod_id=([^&#]+)/.exec(String(MY_URL || ''));
    if (!vid && m1) vid = m1[1];
    var m2 = /(\d+)/.exec(vid);
    if (m2) vid = m2[1];
  } catch (e) {}
  var data = { vod_id: vid, vod_name: '', vod_pic: '', vod_content: '', lines: [] };
  if (vid) {
