    var eps = lines[i].eps || [];
    for (var j = 0; j < eps.length; j++) {
      d.push({
        title: eps[j].name,
        url: eps[j].url,
        col_type: 'text_3'
      });
    }
  }
  setResult(d);
};

$.exports = UI;
})();
