            if (!play) return 'toast://未解析到播放地址';
            if (play.indexOf('http') !== 0) play = M.HOST + play;
            return JSON.stringify({
                urls: [play],
                names: ['播放'],
                headers: [{
                    Referer: M.HOST + '/',
                    'User-Agent': M.UA
                }]
            });
        } catch (e) {
            return 'toast://解析失败';
        }
    })
};
