  // 解析播放页 VOD JSON，返回所有线路 [{name, eps:[{name,url}]}]
  _parseVodAll: function (h) {
    var res = [];
    if (!h) return res;
    var idx = h.indexOf('const VOD');
    if (idx < 0) return res;
    var js = h.indexOf('{', idx);
    if (js < 0) return res;
    var depth = 0, inStr = false, esc = false, end = -1;
    for (var i = js; i < h.length; i++) {
      var ch = h.charAt(i);
      if (inStr) {
        if (esc) esc = false;
        else if (ch === '\\') esc = true;
        else if (ch === '"') inStr = false;
      } else {
        if (ch === '"') inStr = true;
        else if (ch === '{') depth++;
        else if (ch === '}') {
          depth--;
          if (depth === 0) { end = i; break; }
        }
      }
      if (i - js > 500000) break;
    }
    if (end < 0) return res;
    try {
      var v = JSON.parse(h.substring(js, end + 1));
      var lines = v.lines || [];
      for (var li = 0; li < lines.length; li++) {
        var line = lines[li];
        var eps = [];
        var epsArr = line.eps || [];
        for (var k = 0; k < epsArr.length; k++) {
          var t = epsArr[k].t || ('第' + (k + 1) + '集');
          var u = epsArr[k].u || '';
          if (u) eps.push({ name: t, url: u + '#isVideo=true#' });
        }
        if (eps.length) {
          res.push({ name: line.name || ('线路' + (li + 1)), eps: eps });
        }
      }
    } catch (e) {}
    return res;
  },

  _u: function (u) {
    if (!u) return '';
    u = u.trim();
    if (u.indexOf('//') === 0) return 'https:' + u;
    if (u.indexOf('http') === 0) return u;
    if (u.charAt(0) === '/') return X.HOST + u;
    return X.HOST + '/' + u;
  },

  _clean: function (s) {
    if (!s) return '';
    s = String(s).replace(/<[^>]+>/g, '');
    s = s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
         .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ');
