      return;
    }

    var cur = 0;
    try { cur = parseInt(getMyVar('xy_line', '0'), 10) || 0; } catch (e4) {}
    if (cur >= sidList.length) cur = 0;
    var curSid = sidList[cur];

    // 取第一线路播放页，VOD JSON 里包含所有线路（一次抓取）
