    var allLines = X._parseVodAll(ph);
    if (!allLines.length) {
      setError('未解析到选集');
      return;
    }
    // 线路名去重
    var rawNames = allLines.map(function (l) { return l.name; });
    var allSame = rawNames.length > 1;
    for (var ni = 1; ni < rawNames.length; ni++) {
      if (rawNames[ni] !== rawNames[0]) { allSame = false; break; }
    }
