  var txt = '';
  try {
    var r = fetch(url, {method: 'POST', headers: {'Content-Type': 'application/json', 'User-Agent': X.UA, 'Referer': X.HOST + '/search.html'}, body: JSON.stringify(obj)});
    if (r === null || r === undefined) return '';
    txt = String(r);
    if (txt === 'error') return '';
  } catch (e) { txt = ''; }
  return txt || '';
};

X.unesc = function (s) {
  if (!s) return '';
  s = String(s);
  var map = {amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' '};
  s = s.replace(/&([a-zA-Z]+);/g, function (m, n) { return (n in map) ? map[n] : m; });
  s = s.replace(/&#(\d+);/g, function (m, n) {
    n = parseInt(n, 10);
    if (n > 0xFFFF) { n -= 0x10000; return String.fromCharCode(0xD800 + (n >> 10), 0xDC00 + (n & 0x3FF)); }
    return String.fromCharCode(n);
  });
  s = s.replace(/&#x([0-9a-fA-F]+);/g, function (m, n) {
    n = parseInt(n, 16);
    if (n > 0xFFFF) { n -= 0x10000; return String.fromCharCode(0xD800 + (n >> 10), 0xDC00 + (n & 0x3FF)); }
    return String.fromCharCode(n);
  });
  return s;
};

X._u = function (u) {
  if (!u) return '';
  u = String(u).trim();
  if (u.indexOf('//') === 0) return 'https:' + u;
  if (/^https?:/i.test(u)) return u;
  if (u.charAt(0) === '/') return X.HOST + u;
  return X.HOST + '/' + u;
};

// 总页数 = 页面内最大 list 号 + 1（亚洲性爱 89、电影 248）
X._total = function (html) {
  if (!html) return 1;
  var nums = [], m, re = /list_(\d+)\.html/g;
  while ((m = re.exec(html)) !== null) nums.push(parseInt(m[1], 10));
  if (!nums.length) return 1;
  var mx = nums[0];
  for (var i = 1; i < nums.length; i++) if (nums[i] > mx) mx = nums[i];
  return mx + 1;
};

// 列表卡片：<a href="/htm/..." title="..."> + 900 字符内 data-original（src 是 loading.svg，必须取 data-original）
X._items = function (html) {
  var out = [];
  if (!html) return out;
  var seen = {};
  var re = /href="(\/htm\/[^"]+)"[^>]*title="([^"]+)"/g, m;
  while ((m = re.exec(html)) !== null) {
    var path = m[1];
    if (seen[path]) continue;
    var seg = html.substring(m.index, m.index + 900);
    var im = /data-original="([^"]+)"/.exec(seg);
    var title = X.unesc(m[2]).trim();
    if (!im || !title) continue;
    seen[path] = 1;
    out.push({
      vod_id: path,
      vod_name: title,
      vod_pic: X._u(im[1]),
      vod_remarks: ''
    });
  }
  return out;
};

// 卡片：vod_id 只放详情路径（约 45 字符，无 scheme；复合数据绝不塞卡片 URL，碧娜夫人 v1 翻车教训）；&pic= 供详情封面兜底；@rule 调 UI.detail
X._cards = function (items) {
