// 快活影院 UI uikhyy（QQ音乐 v19 uiq16 风格：分类胶囊 + 圆角大搜索框 + ▍标题 + movie_3）
(function () {
var UI = {};
UI.engine = 'khyy';
UI.MV = 'khyy_';

// 顶部横滑分类胶囊行：1-based（CATS[catIdx-1]）；选中纯绿底 #22c55e + ✓ + 深色字
UI.navs = function (d, cats, current) {
  for (var j = 0; j < cats.length; j++) {
    var idx = String(j + 1);
    var active = String(current) === idx;
    d.push({
      title: (active ? '✓ ' : '') + cats[j].name,
      col_type: 'scroll_button',
      url: $('#noLoading##noRecordHistory#').lazyRule(function (s) {
        putMyVar('khyy_cat', s);
        putMyVar('khyy_pg', '1');
        refreshPage(true);
        return 'hiker://empty';
      }, idx),
      extra: {backgroundColor: active ? '#22c55e' : ''}
    });
  }
  d.push({col_type: 'line_blank'});
};

// 搜索框：fypage 子页（标准写法：$.toString 包裹，先存关键词再开子页）
UI.searchBox = function (d) {
  d.push({
    title: '请输入内容',
    desc: '🔍 搜索',
    col_type: 'input',
    url: $.toString(function () {
      if (input) {
        putMyVar('khyy_keyword', input);
        return $('hiker://empty?page=fypage').rule(function () {
          $.require('uikhyy').searchPage();
        });
      }
      return 'hiker://empty';
    })
  });
};

// 搜索子页：kw 链 getParam('kw') → myVar('khyy_keyword') → MY_KEYWORD，含 %xx 先 decodeURIComponent 一次防双编码
UI.searchPage = function () {
  var kw = '';
  try { kw = getParam('kw') || ''; } catch (e) {}
  if (!kw) { try { kw = getMyVar('khyy_keyword', ''); } catch (e2) {} }
  if (!kw) { try { kw = MY_KEYWORD || ''; } catch (e3) {} }
  while (/%[0-9a-fA-F]{2}/.test(kw)) { try { kw = decodeURIComponent(kw); } catch (e) { break; } }
  setResult(UI.renderSearch($.require('khyy').search(kw, 1)));
};

// 翻页：亚色模式（putMyVar + refreshPage(false)）；显隐按 pg < pc 判断
UI.pager = function (d, pg, pc) {
  if (pc <= 1) return;
  d.push({col_type: 'line_blank'});
  if (pg > 1) {
    d.push({
      title: '上一页',
      url: $('#noLoading#').lazyRule(function (p) {
        putMyVar('khyy_pg', String(parseInt(p, 10) - 1));
