      }, String(pg)),
      col_type: 'text_1'
    });
  }
  if (pg < pc) {
    d.push({
      title: '下一页（' + pg + '/' + pc + '）',
      url: $('#noLoading#').lazyRule(function (p) {
        putMyVar('khyy_pg', String(parseInt(p, 10) + 1));
        refreshPage(false);
        return 'hiker://empty';
      }, String(pg)),
      col_type: 'text_1'
