                if (p.charAt(0) === '/') return 'URI="' + root + p + '"';
                return 'URI="' + base + p + '"';
            }));
        } else if (/^(https?:|data:|file:)/.test(S)) {
            out.push(S);
        } else if (S.charAt(0) === '/') {
            out.push(root + S);
