    /* 关键词优先级：URL 内 ##kw:（翻页后仍保留） > 参数 > MY_KEYWORD > KEY */
    var k = '';
    var uu = '';
    try { uu = String(MY_URL || ''); } catch (eU) { uu = ''; }
    var um = uu.match(/##kw:([^#]+)/);
    if (um) {
      try { k = decodeURIComponent(um[1]); } catch (eD) { k = um[1]; }
    }
    if (!k) {
      try {
        k = String((kw === null || kw === undefined) ? '' : kw);
        if (!k) k = String((typeof MY_KEYWORD !== 'undefined' && MY_KEYWORD) ? MY_KEYWORD : '');
        if (!k) k = String((typeof KEY !== 'undefined' && KEY) ? KEY : '');
      } catch (e0) { k = ''; }
    }
    k = k.replace(/^\s+|\s+$/g, '');
    var pg = 1;
    try { pg = parseInt(MY_PAGE, 10) || 1; } catch (e1) { pg = 1; }
    if (pg < 1) pg = 1;

    var d = [];
    if (!k) {
      d.push({ title: '请输入搜索关键词', url: 'hiker://empty', col_type: 'text_1' });
      setResult(d);
      return;
    }
    var html = req(searchUrl(k, pg), REF);
    var cards = parseCards(html);
    try { setPageTitle('搜索「' + k + '」'); } catch (eT) { /* ignore */ }
    if (!cards.length) {
      d.push({ title: '没有找到相关内容', desc: '关键词：' + k, url: 'hiker://empty', col_type: 'text_1' });
      setResult(d);
      return;
    }
    for (var c = 0; c < cards.length; c++) d.push(card(cards[c]));
    setResult(d);
  }

  /* ---------- 详情 ---------- */
  function detail() {
    var u = String(MY_URL || '');
    /* 兼容 v1 的 5 段与 v2 的 6 段（第 6 段是列表 cover）。
     * 坑：URL 尾部是 `@rule=js:$.require(...)`，若分段用 [^#]* 会把整个 @rule 串吃进 hits/cover，
     * 导致 hits 变成 `27023@rule=js:...`、cover 变成 `https%3A...@rule=js:...`。
     * 因此每段都排除 @（cover 走 encodeURIComponent，裸 @ 已被转成 %40，不会被误伤）。 */
    var mm = u.match(/##d:(\d+)\|(\d+)\|(\d+)\|([^|@#]*)\|([^|@#]*)(?:\|([^|@#]*))?/);
    if (!mm) {
      setResult([{ title: '参数错误', desc: '请返回重新进入', url: REF, col_type: 'text_1' }]);
      return;
    }
    var id = mm[1], sid = mm[2], nid = mm[3];
    var dur = clean(mm[4] || '');
    var hits = clean(mm[5] || '');
    var listCover = '';
    if (mm[6]) {
      try { listCover = decodeURIComponent(mm[6]); } catch (eLC) { listCover = mm[6]; }
      listCover = String(listCover).replace(/\\\//g, '/');
    }

    var page = playUrl(id, sid, nid);
    var html = req(page);
    var d = [];

    var title = '';
    /* 优先用播放页 operation-bottom 的第一个 li（站点原始标题，最干净） */
    var om = html.match(/<ul class="operation-bottom">\s*<li>([\s\S]*?)<\/li>/);
    if (om) title = clean(om[1]);
    if (!title) {
      var tm = html.match(/<title>([\s\S]*?)<\/title>/);
      if (tm) {
        title = clean(tm[1]);
        title = title.replace(/^在线播放/, '');
        title = title.replace(/\s*第\d+集\s*-[\s\S]*$/, '');
        title = title.replace(/\s+-\s+[\s\S]*$/, '');
      }
    }
    if (!title) title = '详情';

    var cover = '';
    var pm = html.match(/background-image:\s*url\((https?:\/\/[^)]+)\)/);
    if (pm) cover = pm[1];
    if (!cover) {
      var sm = html.match(/"poster"\s*:\s*"([^"]+)"/);
      if (sm) cover = String(sm[1]).replace(/\\\//g, '/');
    }
    /* 详情页没给封面（popup 与 poster 都改版）时，回退列表 cover，保证播放链不断 */
    if (!cover && listCover) cover = listCover;
    if (!dur) {
      var dm = html.match(/class="play-time">([^<]*)</);
      if (dm) dur = clean(dm[1]);
    }
    var upd = '';
    var um = html.match(/更新时间：<span>([^<]*)<\/span>/);
    if (um) upd = clean(um[1]);

    try { setPageTitle(title); } catch (eT) { /* ignore */ }

    if (cover) {
      d.push({
        col_type: 'card_pic_1',
        title: title,
        desc: '',
        pic_url: cover,
        url: $('hiker://empty##p:' + id + '|' + sid + '|' + nid + '|' + encodeURIComponent(cover || '')).lazyRule(function (pageName, pid, psid, pnid, ppic) {
          return $.require('hiker://page/' + pageName).playById(pid, psid, pnid, ppic);
        }, PAGE, id, sid, nid, cover || ''),
        extra: { lineVisible: false }
      });
    }

    var meta = [];
    if (dur) meta.push('时长 ' + dur);
    if (hits) meta.push('播放 ' + hits);
    if (upd) meta.push('更新 ' + upd);
    d.push({
      col_type: 'flex_button',
      title: title + (meta.length ? '\u3000' + meta.join(' · ') : ''),
      url: 'hiker://empty',
      extra: { backgroundColor: '#2f2f2f', textColor: '#ffffff', lineVisible: false }
    });

    d.push({
      col_type: 'flex_button',
      title: '\u25b6 播放' + (dur ? '\u3000' + dur : ''),
      url: $('hiker://empty##p:' + id + '|' + sid + '|' + nid + '|' + encodeURIComponent(cover || '')).lazyRule(function (pageName, pid, psid, pnid, ppic) {
        return $.require('hiker://page/' + pageName).playById(pid, psid, pnid, ppic);
      }, PAGE, id, sid, nid, cover || ''),
      extra: { backgroundColor: '#ef9c11', textColor: '#ffffff', lineVisible: false }
    });

    /* 猜你喜欢（播放页 scrollBar） */
    var li = html.indexOf('id="scrollBar"');
    if (li > 0) {
      var seg = html.substring(li, Math.min(html.length, li + 40000));
      var likes = parseCards(seg);
      var kept = [];
      for (var k = 0; k < likes.length; k++) if (likes[k].id !== id) kept.push(likes[k]);
      if (kept.length) {
        d.push({
          col_type: 'flex_button',
          title: '\u258d 猜你喜欢',
          url: 'hiker://empty',
          extra: { backgroundColor: '#2e86c1', textColor: '#ffffff', lineVisible: false }
        });
        for (var q = 0; q < kept.length; q++) d.push(card(kept[q]));
      }
    }

    setResult(d);
  }

  /* ---------- 播放 ---------- */
  /* 三级来源：① 传入 cover 目录推导 → ② 播放页 popup/poster 目录推导 → ③ player_aaaa.url
   * 站点只对「免费专区」下发 player_aaaa；其余集 player_aaaa 被服务端整段删除，
   * 但 popup 背景图 / 列表 data-src 都暴露同一个 CDN 目录，故目录推导是主路径。 */
  function playById(id, sid, nid, pic) {
    /* ① 传入 cover（详情页 cover 或列表 cover）目录推导 */
    var c1 = m3u8Of(pic);
    if (c1 && probeM3u8(c1)) return c1 + '#isM3u8##isVideo=true#';
    /* ② 播放页里的 cover（popup 背景图 / poster）目录推导，兼 player_aaaa.url */
    var html = req(playUrl(id, sid, nid));
    var p = parsePlay(html);
    if (p) return p + '#isM3u8##isVideo=true#';
    return 'toast://该视频暂无可播放地址';
  }

  return {
    home: home,
    browse: browse,
    search: search,
    detail: detail,
    playById: playById
  };
})();
"}]

