                try{let hot=this.payload(this.request('/api/v1/hot-searches?period=recent'));if(Array.isArray(hot)&&hot.length){d.push(this.sectionTitle('🔥 官方热搜','点击直接搜索'));hot.forEach((x,i)=>d.push({title:(i<3?'🔥 ':'')+this.cleanText(x.name)+(x.heat?' · '+x.heat:''),url:$('#noLoading#').lazyRule((w)=>{putMyVar('keyword',w);$.require('mdai').saveSearchWord(w);refreshPage(false);return 'hiker://empty';},x.name),col_type:'scroll_button'}));d.push({col_type:'blank_block'});}}catch(ignore){}
                let his=this.readList(this.searchKey);if(his.length){d.push(this.sectionTitle('最近搜索','本地记录'));his.forEach(w=>d.push({title:this.maskText(w),url:$('#noLoading#').lazyRule((x)=>{putMyVar('keyword',x);refreshPage(false);return 'hiker://empty';},w),col_type:'scroll_button'}));d.push({title:'清空',url:$('#noLoading#').lazyRule((k)=>{setItem(k,'[]');refreshPage(false);return 'toast://搜索记录已清空';},this.searchKey),col_type:'scroll_button'});d.push({col_type:'blank_block'});}
