const 分类标题 = 'a&&Text'
const 分类链接 = 'a&&href'
MY_URL = MY_URL.replace('hiker://empty##', '')

let true_url = getVar(MY_RULE.url, MY_URL)
const page = MY_PAGE
if (getVar(MY_RULE.url)) {
    true_url = true_url.replace('vod/type/id', 'vod/show/id').replace('.html', '/page/' + page + '.html')+'/page/' + page
}

var html = request(true_url)
